"""Build an inspectable source-bound native-prefix companion; no training."""
from pathlib import Path
import json
from mora3.data.grh_research_traces import load_pinned_trace, as_reasoning_trace, verify_tropical_reference, REVISION
from mora3.reasoning.trajectory_contracts import prefix_record

ROOT=Path(__file__).resolve().parents[1]
CASES=(('photonic-0','trained.covariance'),('tropical-attention','layer0.context'),('causal-soft-moe','layer0.moe.output'))
paths={x['id']:x['file'] for x in json.loads((ROOT/'tests/fixtures/grh_research/manifest.json').read_text())['traces']}
rows=[]
for name,target in CASES:
    source=load_pinned_trace(ROOT/'tests/fixtures/grh_research',name)
    raw=source.document();trace=as_reasoning_trace(source,target_node_id=target)
    selected={f.name[7:] for f in trace.facts if f.name.startswith('tensor:')}
    operations=[n for n in raw['nodes'] if n['id'] in selected and n['inputs']]
    prefixes=[]
    for count in range(len(operations)+1):
        receipt=prefix_record(trace,tuple(s.key for s in trace.steps[:count]))
        prefixes.append(dict(completed=count,visible=[f['name'] for f in receipt['state']['facts']],
            condition_sha256=receipt['condition_sha256']))
    rows.append(dict(id=name,source_path=paths[name],title=raw.get('title',name),source_sha256=source.sha256,
        evidence_kind=raw['provenance']['kind'],source_scope=raw['provenance'].get('scope',''),
        original_split=raw['provenance'].get('split','source reference; no train split supplied'),
        native_split=trace.split,target=target,nodes=[n for n in raw['nodes'] if n['id'] in selected],
        operations=operations,prefixes=prefixes,complete_source_nodes=len(raw['nodes']),
        selected_source_nodes=len(selected),training_admission=False,
        reference=verify_tropical_reference(source) if name=='tropical-attention' else None))
data=dict(schema='Mora3.GRHBridgeExplorer/v1',source_revision=REVISION,cases=rows,
    node_count_semantics='source computation DAG versus linear known-program execution states',training_runs=0)
PAGE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mora-3 × GRH · Computation prefixes</title><style>
:root{--ink:#163c44;--muted:#566b70;--line:#c7d7d8;--paper:#f4f7f3;--accent:#08776f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:35px 24px}a{color:#096d7d}h1{font-size:clamp(32px,5vw,56px);line-height:1.12;letter-spacing:-.04em;margin:15px 0 20px}h2{font-size:24px;line-height:1.25;margin:0 0 16px}p{max-width:920px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:12px;font-weight:750}.notice{border-left:4px solid #98752c;background:#ece9db;padding:13px 18px;margin:22px 0}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:15px;margin:23px 0}.controls label{display:flex;flex-direction:column;gap:6px;font-size:14px;font-weight:650;flex:1 1 240px}select,button{min-height:44px;padding:9px 12px;border:1px solid #859fa5;border-radius:5px;background:white;font:inherit;color:var(--ink)}input[type=range]{min-height:44px;width:100%}button{cursor:pointer}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #a45c31;outline-offset:3px}.card{background:white;border:1px solid var(--line);border-radius:10px;padding:23px;margin-bottom:22px;min-width:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.stats{display:flex;flex-wrap:wrap;gap:30px;border-top:1px solid var(--accent);padding:14px 0;margin:22px 0}.stats strong{display:block;font-size:27px}.stats span{font-size:13px}.scroll{overflow:auto;max-width:100%}#timeline svg{display:block;min-width:100%}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px 5px;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}th{font-size:12px}#facts td:last-child{white-space:nowrap}td{overflow-wrap:anywhere}.caption{color:var(--muted);font-size:14px}.code{font:13px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.55 ui-monospace,monospace;background:#eef3f2;padding:15px;border-radius:6px;max-height:320px;overflow:auto}.facts{max-height:370px;overflow:auto}.tag{display:inline-block;background:#e1efeb;color:#125c54;border-radius:20px;padding:4px 10px;font-size:12px;font-weight:700}.target{background:#fbf2e6}footer{border-top:1px solid var(--line);padding:20px 0;color:var(--muted);font-size:14px}details{margin-top:15px}summary{cursor:pointer}.wide{grid-column:1/-1}@media(max-width:700px){main{padding:22px 14px}.grid{grid-template-columns:1fr}.card{padding:16px}.controls{gap:10px}.controls label{flex-basis:100%}h2{font-size:22px}.stats{gap:20px}}
</style></head><body><main><a href="../index.html">Mora-3 research</a><p class="eyebrow">GRH research × native complete-prefix reasoning</p><h1>Preserve the computation.<br>Hide the answer.</h1><p>A pinned numerical source becomes an inspectable, evidence-typed Mora-3 reasoning record. Move through its execution schedule to see exactly which tensors exist at each prefix—and which result is still withheld.</p><div class="notice"><strong>Reference integration, not new training.</strong> These are original fixed-weight numerical references or saved checkpoint replays from GRH-research. Mora-3 treats all three as evaluation-only. No GRH proof, biomedical validity, blind generalization or completed μTransfer run is inferred.</div>
<div class="controls"><label for="case">Pinned source / target operation<select id="case"></select></label><label for="step">Completed operations <output id="step-value"></output><input id="step" type="range" min="0" value="0" step="1"></label><button id="export">Export current SVG</button></div>
<div class="stats"><div><span>Original source DAG nodes</span><strong id="all-nodes"></strong></div><div><span>Target and all its ancestors</span><strong id="selected-nodes"></strong></div><div><span>Visible native facts</span><strong id="visible-count"></strong></div><div><span>Mora training runs</span><strong>0</strong></div></div>
<section class="card"><h2>A complete known-program execution prefix</h2><div id="timeline" class="scroll"></div><p class="caption">Each box is an execution state, not a source tensor, biological time point or searched tree branch. A step executes one original operation. The original source DAG dependencies remain attached to every derived fact; shared ancestors are not duplicated as independent evidence. The horizontal panel scrolls when necessary.</p></section>
<div class="grid"><section class="card"><h2>What the native predictor can see</h2><span class="tag" id="kind"></span><p id="prefix-summary" aria-live="polite"></p><div class="facts"><table><thead><tr><th>Visible tensor</th><th>Original axes / shape</th><th>Type</th></tr></thead><tbody id="facts"></tbody></table></div><p class="caption">The declared operation program is also a known condition. This is a given-program computation task, not prediction with hidden target topology. Tensor units are not invented from their axes.</p></section>
<section class="card target"><h2>Reference result—not a prefix input</h2><p id="target-name" class="code"></p><p id="target-status"></p><button id="reveal" aria-expanded="false">Inspect retained reference tensor</button><pre id="target-values" hidden></pre><p class="caption">Revealing the source value changes this display only. It does not modify the importer or add the answer to the native predictor's prefix. The array remains complete in the source file; the display is bounded to32 scalar values.</p><details><summary>Actual numerical verification</summary><pre id="numerical-check"></pre></details></section>
<section class="card wide"><h2>Reproduction and evidence boundaries</h2><p id="scope"></p><table><tbody><tr><th>Source kind</th><td id="source-kind"></td></tr><tr><th>Source split wording</th><td id="source-split"></td></tr><tr><th>Mora usage</th><td>Test-only numerical reference, not admitted training</td></tr><tr><th>Original source SHA256</th><td id="source-hash" class="code"></td></tr><tr><th>Current prefix SHA256</th><td id="prefix-hash" class="code"></td></tr></tbody></table><p>The biological GRH-ConformerResponse dataset is a different source. Its computed MMFF94/electronic/nuclear labels and inactive cross-corpus exclusion masks remain separate; this numerical bridge does not enroll those records or override their conflicts.</p><p><a id="source-link">Open the exact original trace</a> · <a href="https://amelie-iska.github.io/GRH-research/">GRH research companion</a> · <a href="../grh_research_integration_20261113.md">Integration methods and limits</a></p></section></div>
<footer>Original numerical values are preserved. No source repository scripts, foreign checkpoints, network model calls or optimizers run in this page.</footer>
<script type="application/json" id="data">__DATA__</script><script>'use strict';const DATA=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state={case:0,step:0,reveal:false};
for(const [i,c] of DATA.cases.entries())$('case').add(new Option(c.id+' → '+c.target,i));
function timeline(c,k){const n=c.operations.length,W=Math.max(900,(n+1)*165),h=190;let s=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${h}" viewBox="0 0 ${W} ${h}" role="img" aria-label="Actual native computation execution prefix"><title>${escape(c.id)} · ${k} completed operations</title><rect width="${W}" height="${h}" fill="white"/><text x="18" y="25" font-family="sans-serif" font-size="15" fill="#163c44">${escape(c.id)} · test-only source reference</text>`;
 for(let i=0;i<=n;i++){const x=18+i*165,known=i<=k,label=i===0?'Known program + roots':c.operations[i-1].id; if(i<n)s+=`<path d="M ${x+137} 90 H ${x+155} l -5 -4 M ${x+155} 90 l -5 4" fill="none" stroke="#839b9e"/>`;s+=`<rect x="${x}" y="55" width="137" height="72" rx="7" fill="${known?'#e0efea':'#f6eee3'}" stroke="${i===k?'#08776f':'#b9c9cb'}" stroke-width="${i===k?2:1}"/><text x="${x+10}" y="78" font-family="sans-serif" font-size="13" fill="#163c44">State ${i} · ${known?'available':'future'}</text><text x="${x+10}" y="101" font-family="sans-serif" font-size="11" fill="#163c44">${escape(label.length>20?label.slice(0,18)+'…':label)}</text>`;}s+='<text x="18" y="159" font-family="sans-serif" font-size="12" fill="#566b70">Execution schedule of the selected ancestor DAG; this is not a learned search forest or physical causal graph.</text></svg>';return s;}
function render(url=true){const c=DATA.cases[state.case];state.step=Math.max(0,Math.min(c.operations.length,state.step));const p=c.prefixes[state.step],visible=new Set(p.visible);$('case').value=state.case;$('step').max=c.operations.length;$('step').value=state.step;$('step-value').textContent=`${state.step} / ${c.operations.length}`;$('all-nodes').textContent=c.complete_source_nodes;$('selected-nodes').textContent=c.selected_source_nodes;$('visible-count').textContent=p.visible.length;$('timeline').innerHTML=timeline(c,state.step);$('kind').textContent=c.evidence_kind;$('prefix-summary').textContent=state.step<c.operations.length?`Next operation: ${c.operations[state.step].id}. Its result has not entered this prefix.`:'All selected source operations are complete; this terminal state is not a pre-answer prediction input.';
 $('facts').innerHTML=c.nodes.filter(n=>visible.has('tensor:'+n.id)).map(n=>`<tr><td>${escape(n.id)}</td><td>${escape(n.tensor.axes.join(' × ')||'scalar')}<br>${escape(JSON.stringify(n.tensor.shape))}</td><td>${escape(n.tensor.dtype)}</td></tr>`).join('');const target=c.nodes.find(n=>n.id===c.target);$('target-name').textContent=c.target;$('target-status').textContent=visible.has('tensor:'+c.target)?'This is now a completed terminal value. Return to an earlier prefix to inspect pre-answer conditions.':'Withheld from the selected prefix.';const t=target.tensor;const flat=(t.values??t.real);const values=Array.isArray(flat)?flat.flat(Infinity):[flat];$('target-values').textContent=JSON.stringify({dtype:t.dtype,shape:t.shape,axes:t.axes,displayed_values:values.slice(0,32),total_scalar_values:values.length,imaginary_part_present:!!t.imag},null,2);$('target-values').hidden=!state.reveal;$('reveal').setAttribute('aria-expanded',String(state.reveal));$('reveal').textContent=state.reveal?'Hide reference tensor':'Inspect retained reference tensor';$('numerical-check').textContent=c.reference?JSON.stringify(c.reference,null,2):'Shape, dtype, dependency and native-prefix checks passed. Source-declared physics checks are retained but are not independently re-proved by this view.';$('source-kind').textContent=c.evidence_kind;$('source-split').textContent=c.original_split;$('scope').textContent=c.source_scope;$('source-hash').textContent=c.source_sha256;$('prefix-hash').textContent=p.condition_sha256;$('source-link').href=`https://github.com/amelie-iska/GRH-research/tree/${DATA.source_revision}/web/data/architecture/${c.source_path}`;
 if(url)history.replaceState(null,'','#'+new URLSearchParams({case:state.case,step:state.step}).toString());}
$('case').onchange=()=>{state.case=Number($('case').value);state.step=0;state.reveal=false;render();};$('step').oninput=()=>{state.step=Number($('step').value);render();};$('reveal').onclick=()=>{state.reveal=!state.reveal;render(false);};function restore(){const p=new URLSearchParams(location.hash.slice(1)),i=Number(p.get('case')??0),k=Number(p.get('step')??0);state.case=Number.isInteger(i)&&i>=0&&i<DATA.cases.length?i:0;state.step=Number.isInteger(k)?k:0;state.reveal=false;render(false);}window.onhashchange=restore;
$('export').onclick=()=>{const c=DATA.cases[state.case],url=URL.createObjectURL(new Blob([timeline(c,state.step)],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='grh-native-prefix.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),0);};restore();window.GRHBridge={ready:true,data:DATA,state:()=>({...state}),timeline};</script></main></body></html>'''
p=ROOT/'docs/project/grh-research-bridge.html'
p.write_text(PAGE.replace('__DATA__',json.dumps(data,ensure_ascii=True,separators=(',',':')).replace('</','<\\/')))
print(json.dumps(dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,cases=len(rows),source_revision=REVISION,training_runs=0)))
